command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: WECKRUF (Ausführung)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    let fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (!fwMacro) fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.2Y0fhqBb26d4gysu");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Weckruf";
    const ahne = "Zerzal"; 
    const finalEffektName = `${gabenName} (${ahne})`;
    const iconBild = DSK_FW.Symbol(ahne);

    if (DSK_FW.EffektEnde && !globalThis._dskWeckrufRegistered) {
        globalThis._dskWeckrufRegistered = true;
        DSK_FW.EffektEnde.Register("weckruf", finalEffektName, "Die wachsamen Schatten von Zerzal verblassen. Der Weckruf ist nicht mehr aktiv.");
    }

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. CASTER ERMITTELN ---
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    const qs = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");
    let whisperTargets = [...new Set([...game.users.filter(u => u.isGM).map(u => u.id), ...getOwners(casterActor)])].filter(id => game.users.get(id));

    // --- 3. BERECHNUNGEN ---
    const dauerStunden = qs * 2;
    const dauerSekunden = dauerStunden * 3600;
    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';
    const dauerCalc = `<span ${thinStyle}>(${qs} QS x 2)</span>`;

    // --- 4. ZIELE HOLEN ---
    const targets = Array.from(game.user.targets);
    if (targets.length === 0) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle ein Ziel per Target aus!");

    // --- 5. EFFEKTE ANWENDEN ---
    const erfolge = [];

    const originalText = `Das Ziel wird innerhalb der Wirkungsdauer aus dem Schlaf gerissen, wenn eine vorher klar definierte Situation eintritt. Diese muss beim Wirken der Gabe klar definiert werden. „Wenn ein Hund sich heranschleicht“ oder „wenn eine Maus dieses Loch verlässt“ sind ausreichend genaue Vorgaben, „wenn mich jemand angreifen will“ oder „wenn etwas Schlimmes geschieht“ sind zu weit gefasst. Im Zweifelsfalle entscheidet der Spielleiter.`;

    for (let t of targets) {
        if (!t.actor) continue;

        // 🚩 LUNAS FIX: Streng nach Vorlage! ahne: ahne wird übergeben, 
        // damit das Framework das richtige Zerzal-Icon auf dem Bogen generiert.
        await DSK_FW.Effekt.Anwenden({
            name: finalEffektName,
            ahne: ahne,
            beschreibung: originalText,
            qs: qs,
            ziel: t.actor
        });

        // Wirkungsdauer im Effekt nachtragen
        const eff = t.actor.effects.find(e => (e.name || e.label) === finalEffektName);
        if (eff) {
            await eff.update({ duration: { seconds: dauerSekunden } });
        }

        erfolge.push(t.name);
    }

    // --- 6. FLAG-CLEANUP ---
    if (erfolge.length > 0) {
        await casterActor.unsetFlag("world", "letzteGabenQS");
        await casterActor.unsetFlag("world", "letzteGabenMessageId");
    }

    // --- 7. CHAT-KARTE ---
    let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    [...targets, canvas.tokens.controlled[0]].forEach(t => {
        if(t?.actor) Object.entries(t.actor.ownership || {}).filter(([id, lvl]) => lvl === 3).forEach(([id]) => ownerIds.add(id));
    });

    const erfolgHtml = erfolge.length > 0 
        ? `<div style="margin-top: 10px; margin-bottom: 10px;">
               <p style="margin-bottom: 5px;"><span style="color:#18940F; font-weight:bold;">Gewirkt auf:</span></p>
               <ul class="dsklist" style="margin-top:0; font-weight:normal; color: #000;">
                   ${erfolge.map(n => `<li>${n}</li>`).join("")}
               </ul>
           </div>` : ``;

    const cardContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p style="margin-bottom: 8px;"><b>Gabenwirkung:</b></p>
                <p style="margin-top:0; text-align: justify;">Das Ziel wird innerhalb der Wirkungsdauer sofort aus dem Schlaf gerissen, wenn eine vorher <b>klar definierte Situation</b> eintritt.</p>
                <ul class="dsklist" style="margin-bottom: 8px;">
                    <li><b style="color: #18940F;">Gültig:</b> „Wenn ein Hund sich heranschleicht“</li>
                    <li><b style="color: #B30000;">Ungültig:</b> „Wenn etwas Schlimmes geschieht“</li>
                </ul>
                <p style="font-size: 0.9em; color: #555; font-style: italic;">(Im Zweifelsfalle entscheidet der Spielleiter)</p>
                ${erfolgHtml}
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="text-align:center; font-weight:bold; margin-bottom: 0;">
                    Wirkungsdauer:<br>${dauerStunden} Stunden ${dauerCalc}
                </p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: cardContent });
    } else {
        const neueMsg = await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: Array.from(ownerIds).filter(id => game.users.get(id)),
            content: cardContent
        });
        if (neueMsg && erfolge.length === 0) {
            await casterActor.setFlag("world", "letzteGabenMessageId", neueMsg.id);
        }
    }
})();
